<?php
use PHPUnit\Framework\TestCase;
final class Phase9PMPriceBookTest extends TestCase {
 public function test_pm_price_book_upgrade_is_versioned_and_normalized(): void {$b=file_get_contents(__DIR__.'/../../servsys.php');$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString("SERVSYS_DB_VERSION', 12",$b);$this->assertStringContainsString('servsys_pm_plans',$s);$this->assertStringContainsString('servsys_pm_plan_terms',$s);$this->assertStringContainsString('term_months smallint(5) unsigned NOT NULL',$s);$this->assertStringContainsString('UNIQUE KEY plan_term (pm_plan_id,term_months)',$s);$this->assertStringNotContainsString('prevprices_date',$s);$this->assertStringNotContainsString('yr1 decimal',$s);}
 public function test_pm_plans_preserve_legacy_reference_estimate_and_audit_fields(): void {$s=file_get_contents(__DIR__.'/../../src/Database/Schema.php');$this->assertStringContainsString('tm_estimate decimal(13,4) NOT NULL DEFAULT 0.0000',$s);$this->assertStringContainsString('active tinyint(1) NOT NULL DEFAULT 1',$s);$this->assertGreaterThanOrEqual(2,substr_count($s,'created_by bigint(20) unsigned NULL'));$this->assertGreaterThanOrEqual(2,substr_count($s,'updated_by bigint(20) unsigned NULL'));}
 public function test_pm_capabilities_are_company_scoped(): void {$c=file_get_contents(__DIR__.'/../../src/Users/Capabilities.php');$this->assertStringContainsString("VIEW_PM_PLANS = 'servsys_view_pm_plans'",$c);$this->assertStringContainsString("MANAGE_PM_PLANS = 'servsys_manage_pm_plans'",$c);$this->assertGreaterThanOrEqual(2,substr_count($c,'self::VIEW_PM_PLANS'));$this->assertGreaterThanOrEqual(2,substr_count($c,'self::MANAGE_PM_PLANS'));}
 public function test_pm_repositories_scope_data_to_company(): void {foreach(array('PMPlanRepository.php','PMPlanTermRepository.php') as $file){$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/'.$file);$this->assertStringContainsString('CompanyContext::current_company_id()',$p,$file);}}
 public function test_pm_service_validates_terms_and_replaces_them_atomically(): void {$p=file_get_contents(__DIR__.'/../../src/PreventiveMaintenance/PMPlanService.php');$this->assertStringContainsString('unique term lengths',$p);$this->assertStringContainsString('term must be at least one month',$p);$this->assertStringContainsString('term price cannot be negative',$p);$this->assertStringContainsString('START TRANSACTION',$p);$this->assertStringContainsString('ROLLBACK',$p);}
 public function test_pm_admin_requires_nonce_and_manage_permission(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/PMPlansPage.php');$this->assertStringContainsString("check_admin_referer('servsys_save_pm_plan')",$p);$this->assertStringContainsString('Capabilities::MANAGE_PM_PLANS',$p);$this->assertStringContainsString('Search PM Plans',$p);$this->assertStringContainsString('Term Pricing',$p);}
 public function test_pm_admin_is_registered_and_linked_from_configuration(): void {$p=file_get_contents(__DIR__.'/../../src/Plugin.php');$c=file_get_contents(__DIR__.'/../../src/Admin/ConfigurationPage.php');$this->assertStringContainsString('use ServSys\\Admin\\PMPlansPage;',$p);$this->assertStringContainsString('( new PMPlansPage() )->register();',$p);$this->assertStringContainsString("'servsys-pm-plans'",$c);}
}
